python3 - <<'E'
import sqlite3
a=sqlite3.connect('build/herbarium.sqlite');b=sqlite3.connect('/tmp/u.sqlite')
for t in ['site','collector','taxon','specimen']:
    q=f'select * from {t} order by 1'
    if t=='taxon': q='select taxon_id,parent_id,rank,genus,epithet,infra,full_name from taxon order by 1'
    ra,rb=a.execute(q).fetchall(),b.execute(q).fetchall()
    print(t,len(ra),len(rb),ra==rb)
    if ra!=rb:
        d=[(x,y) for x,y in zip(ra,rb) if x!=y];print(d[:5],len(d))
q="select type,name,sql from sqlite_master order by 1,2"
sa={r[:2]:r[2] for r in a.execute(q)};sb={r[:2]:r[2] for r in b.execute(q)}
for k in set(sa)|set(sb):
    if sa.get(k)!=sb.get(k): print(k,'\n',sa.get(k),'\n',sb.get(k))
E
